type workflow struct {
	Permissions any `yaml:"permissions"`
	Jobs        map[string]struct {
		Permissions any `yaml:"permissions"`
	} `yaml:"jobs"`
}

func main() {
	ok := true
	for _, f := range os.Args[1:] {
		b, err := os.ReadFile(f)
		if err != nil {
			fmt.Println("READ ERR", f, err)
			ok = false
			continue
		}
		var w workflow
		if err := yaml.Unmarshal(b, &w); err != nil {
			fmt.Println("YAML ERR", f, err)
			ok = false
			continue
		}
		fmt.Printf("\n%s: workflow permissions = %#v\n", filepath.Base(f), w.Permissions)
