		for n := range w.Jobs {
			names = append(names, n)
		}
		sort.Strings(names)
		for _, n := range names {
			eff := w.Jobs[n].Permissions
			src := "job"
			if eff == nil {
				eff, src = w.Permissions, "workflow"
			}
			mark := "  "
			if eff == nil {
				mark, ok = "!!", false
			}
			fmt.Printf("  %s %-24s from=%-8s effective=%#v\n", mark, n, src, eff)
		}
	}
	if ok {
		fmt.Println("\nOK: valid YAML, every job has effective permissions")
	} else {
		fmt.Println("\nFAIL")
		os.Exit(1)
	}
}
